906	    try {
907	      name = utf8.decode(entry.name);
908	    } catch {
909	      onSkip([...prefix, entry.name.toString()].join('/'), 'file name is not valid UTF-8');
910	      continue;
911	    }
912	    const segments = [...prefix, name];
913	    const full = path.join(dir, name);
914	    if (entry.isDirectory()) {
915	      await walk(full, segments, out, onSkip);
916	    } else if (entry.isFile()) {
917	      out.push({ key: segments.join('/'), path: full });
918	    } else if (entry.isSymbolicLink()) {
919	      onSkip(segments.join('/'), 'symbolic link');
920	    } else {
921	      onSkip(segments.join('/'), 'not a regular file');
922	    }
923	  }
924	}
925	
926	/**
927	 * Splits a key into the path segments of the file it names under the root,
928	 * the reverse of what listFiles() does.
929	 *
930	 * @param {string} key
931	 * @returns {string[] | null} null if the key is not a plain relative path
932	 *   (empty, absolute, an empty, "." or ".." segment, a NUL, a lone
933	 *   surrogate), i.e. names no file inside the root
934	 */
935	export function keySegments(key) {
936	  if (typeof key !== 'string' || !key.isWellFormed() || key.includes('\0')) {
937	    return null;
938	  }
939	  const segments = key.split('/');
940	  if (segments.some((s) => s === '' || s === '.' || s === '..')) {
941	    return null;
942	  }
943	  return segments;
944	}
945	
946	/**
947	 * @param {string} file
948	 * @returns {Promise<string>} SHA-256 of the file's contents, in hex
949	 */
950	export async function sha256File(file) {
951	  const hash = createHash('sha256');
952	  for await (const chunk of fs.createReadStream(file)) {
953	    hash.update(chunk);
954	  }
955	  return hash.digest('hex');
