384	async function writeTree(root, files) {
385	  for (const [rel, content] of Object.entries(files)) {
386	    await fs.mkdir(path.dirname(path.join(root, rel)), { recursive: true });
387	    await fs.writeFile(path.join(root, rel), content);
388	  }
389	}
390	
391	/** Every entry under `root` as "relative/path" -> contents (or "<dir>"/"<symlink>"). */
392	async function readTree(root) {
393	  const out = {};
394	  for (const entry of await fs.readdir(root, { recursive: true, withFileTypes: true })) {
395	    const full = path.join(entry.path, entry.name);
396	    const rel = path.relative(root, full).split(path.sep).join('/');
397	    if (entry.isSymbolicLink()) {
398	      out[rel] = '<symlink>';
399	    } else if (entry.isDirectory()) {
400	      out[rel] = '<dir>';
401	    } else {
402	      out[rel] = (await fs.readFile(full)).toString('latin1');
403	    }
404	  }
405	  return out;
406	}
